SELECT * FROM transaction
WHERE user_id = #{userId}
ORDER BY transaction_date DESC, created_at DESC

SELECT * FROM transaction
WHERE user_id = #{userId}
  AND transaction_date BETWEEN #{startDate} AND #{endDate}
ORDER BY transaction_date DESC, created_at DESC

SELECT * FROM transaction
WHERE user_id = #{userId} AND category_id = #{categoryId}
ORDER BY transaction_date DESC, created_at DESC
